"""Improved PII redactor with enhanced detection for Credit Cards using Luhn validation."""
import re

PATTERNS = [
    ("EMAIL", re.compile(r"[\w.]+@[\w]+\.\w+")),
    ("PHONE", re.compile(r"\d{3}-\d{3}-\d{4}")),
    ("SSN", re.compile(r"\b\d{3}-\d{2}-\d{4}\b")),
    ("CREDIT_CARD", re.compile(r"\b(?:\d[ -]*?){13,19}\b")),
]


def luhn_check(card_num: str) -> bool:
    """Validate credit card number using Luhn algorithm."""
    digits = [int(c) for c in card_num if c.isdigit()]
    if not (13 <= len(digits) <= 19):
        return False
    checksum = 0
    double = False
    for d in reversed(digits):
        if double:
            d *= 2
            if d > 9:
                d -= 9
        checksum += d
        double = not double
    return checksum % 10 == 0


def find_pii(text):
    """Return a list of (start, end, label) spans that contain PII."""
    spans = []
    for label, pattern in PATTERNS:
        for m in pattern.finditer(text):
            candidate = m.group(0)
            if label == "CREDIT_CARD":
                if not luhn_check(candidate):
                    continue
            spans.append((m.start(), m.end(), label))
    return spans
